def count_bidirectional(tuples):
    # Convert each tuple to a sorted tuple to make bidirectional pairs identical
    normalized_tuples = [tuple(sorted(t)) for t in tuples]
    # Count the occurrences of each normalized tuple
    count = {}
    for nt in normalized_tuples:
        if nt in count:
            count[nt] += 1
        else:
            count[nt] = 1
    # Sum the occurrences that are at least 2 (indicating a bidirectional pair)
    return sum(value for value in count.values() if value >= 2)

